using System;
using Framework.Parameters;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// RuntimeParameterの値管理、補正計算、
    /// 変更通知および個体の独立性を検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class RuntimeParameterTest : MonoBehaviour
    {
        [Header("テスト設定")]
        [SerializeField]
        [Tooltip("開始時にすべてのテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]
        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 開始時のテスト実行を制御する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行し、結果を集計する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

            try
            {
                TestInitialization();
                TestBaseValue();
                TestCalculation();
                TestModifierManagement();
                TestSourceRemoval();
                TestReset();
                TestEvents();
                TestIndependence();
                TestInvalidInput();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }

            Debug.Log(
                $"【RuntimeParameter テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗したテストを確認してください。"),
                this);
        }

        /// <summary>
        /// 標準的なテスト用定義を生成する。
        /// </summary>
        /// <returns>初期値4、有効範囲0から10の定義</returns>
        private ParameterDefinition<string> CreateDefinition()
        {
            return new ParameterDefinition<string>(
                "MoveSpeed",
                4f,
                0f,
                10f);
        }

        /// <summary>
        /// テスト用の実行時パラメーターを生成する。
        /// </summary>
        /// <returns>標準初期値を持つパラメーター</returns>
        private RuntimeParameter<string> CreateParameter()
        {
            return new RuntimeParameter<string>(
                CreateDefinition());
        }

        /// <summary>
        /// 初期化時の値と定義情報を検証する。
        /// </summary>
        private void TestInitialization()
        {
            var definition = CreateDefinition();

            var parameter =
                new RuntimeParameter<string>(definition);

            bool definitionPassed =
                ReferenceEquals(parameter.Definition, definition);
            Debug.Assert(definitionPassed, "定義の共有", this);
            Check(definitionPassed, "定義の共有");

            bool idPassed = parameter.Id == "MoveSpeed";
            Debug.Assert(idPassed, "識別子の取得", this);
            Check(idPassed, "識別子の取得");

            bool initialPassed = parameter.InitialValue == 4f;
            Debug.Assert(initialPassed, "標準初期値", this);
            Check(initialPassed, "標準初期値");

            bool basePassed = parameter.BaseValue == 4f;
            Debug.Assert(basePassed, "初期基本値", this);
            Check(basePassed, "初期基本値");

            bool valuePassed = parameter.Value == 4f;
            Debug.Assert(valuePassed, "初期最終値", this);
            Check(valuePassed, "初期最終値");

            var custom =
                new RuntimeParameter<string>(definition, 7f);

            bool customPassed =
                custom.InitialValue == 7f &&
                custom.BaseValue == 7f &&
                custom.Value == 7f;
            Debug.Assert(customPassed, "個体固有の初期値", this);
            Check(customPassed, "個体固有の初期値");
        }

        /// <summary>
        /// 基本値の変更と範囲制限を検証する。
        /// </summary>
        private void TestBaseValue()
        {
            var parameter = CreateParameter();

            bool changePassed =
                parameter.SetBaseValue(6f) &&
                parameter.BaseValue == 6f &&
                parameter.Value == 6f;
            Debug.Assert(changePassed, "基本値の変更", this);
            Check(changePassed, "基本値の変更");

            bool samePassed = !parameter.SetBaseValue(6f);
            Debug.Assert(samePassed, "同一基本値の変更省略", this);
            Check(samePassed, "同一基本値の変更省略");

            bool maxPassed =
                parameter.SetBaseValue(20f) &&
                parameter.BaseValue == 10f;
            Debug.Assert(maxPassed, "基本値の上限制限", this);
            Check(maxPassed, "基本値の上限制限");

            bool minPassed =
                parameter.SetBaseValue(-5f) &&
                parameter.BaseValue == 0f;
            Debug.Assert(minPassed, "基本値の下限制限", this);
            Check(minPassed, "基本値の下限制限");

            bool addPassed =
                parameter.AddBaseValue(3f) &&
                parameter.Value == 3f;
            Debug.Assert(addPassed, "基本値への加算", this);
            Check(addPassed, "基本値への加算");

            bool subtractPassed =
                parameter.AddBaseValue(-2f) &&
                parameter.Value == 1f;
            Debug.Assert(subtractPassed, "基本値からの減算", this);
            Check(subtractPassed, "基本値からの減算");
        }

        /// <summary>
        /// 加算補正、乗算補正および範囲制限を検証する。
        /// </summary>
        private void TestCalculation()
        {
            var parameter = CreateParameter();

            parameter.TryAddModifier(
                ParameterModifier.CreateAdditive(2f));

            bool additivePassed = parameter.Value == 6f;
            Debug.Assert(additivePassed, "加算補正の計算", this);
            Check(additivePassed, "加算補正の計算");

            parameter.TryAddModifier(
                ParameterModifier.CreateAdditive(-1f));

            bool negativePassed = parameter.Value == 5f;
            Debug.Assert(negativePassed, "負数補正の計算", this);
            Check(negativePassed, "負数補正の計算");

            parameter.TryAddModifier(
                ParameterModifier.CreateMultiplicative(1.5f));

            bool multiplyPassed = parameter.Value == 7.5f;
            Debug.Assert(multiplyPassed, "乗算補正の計算", this);
            Check(multiplyPassed, "乗算補正の計算");

            parameter.TryAddModifier(
                ParameterModifier.CreateMultiplicative(0.5f));

            bool combinedPassed = parameter.Value == 3.75f;
            Debug.Assert(combinedPassed, "複数補正の計算", this);
            Check(combinedPassed, "複数補正の計算");

            var reversed = CreateParameter();

            reversed.TryAddModifier(
                ParameterModifier.CreateMultiplicative(0.5f));

            reversed.TryAddModifier(
                ParameterModifier.CreateMultiplicative(1.5f));

            reversed.TryAddModifier(
                ParameterModifier.CreateAdditive(-1f));

            reversed.TryAddModifier(
                ParameterModifier.CreateAdditive(2f));

            bool orderPassed =
                reversed.Value == parameter.Value;
            Debug.Assert(orderPassed, "補正種別の計算順序", this);
            Check(orderPassed, "補正種別の計算順序");

            var upper = CreateParameter();

            upper.TryAddModifier(
                ParameterModifier.CreateMultiplicative(100f));

            bool upperPassed = upper.Value == 10f;
            Debug.Assert(upperPassed, "最終値の上限制限", this);
            Check(upperPassed, "最終値の上限制限");

            var lower = CreateParameter();

            lower.TryAddModifier(
                ParameterModifier.CreateAdditive(-100f));

            bool lowerPassed = lower.Value == 0f;
            Debug.Assert(lowerPassed, "最終値の下限制限", this);
            Check(lowerPassed, "最終値の下限制限");

            parameter.TryAddModifier(
                ParameterModifier.CreateMultiplicative(0f));

            bool zeroPassed = parameter.Value == 0f;
            Debug.Assert(zeroPassed, "ゼロ倍率の適用", this);
            Check(zeroPassed, "ゼロ倍率の適用");
        }

        /// <summary>
        /// 補正の登録、検索、解除を検証する。
        /// </summary>
        private void TestModifierManagement()
        {
            var parameter = CreateParameter();

            var modifier =
                ParameterModifier.CreateAdditive(2f);

            bool emptyPassed =
                !parameter.HasModifiers &&
                parameter.ModifierCount == 0;
            Debug.Assert(emptyPassed, "初期補正一覧", this);
            Check(emptyPassed, "初期補正一覧");

            bool addPassed =
                parameter.TryAddModifier(modifier) &&
                parameter.ModifierCount == 1 &&
                parameter.HasModifiers;
            Debug.Assert(addPassed, "補正の追加", this);
            Check(addPassed, "補正の追加");

            bool duplicatePassed =
                !parameter.TryAddModifier(modifier) &&
                parameter.ModifierCount == 1;
            Debug.Assert(duplicatePassed, "重複登録の拒否", this);
            Check(duplicatePassed, "重複登録の拒否");

            bool searchPassed =
                parameter.HasModifier(modifier.Id) &&
                parameter.TryGetModifier(
                    modifier.Id,
                    out ParameterModifier found) &&
                ReferenceEquals(found, modifier);
            Debug.Assert(searchPassed, "登録済み補正の検索", this);
            Check(searchPassed, "登録済み補正の検索");

            bool missingPassed =
                !parameter.TryGetModifier(
                    Guid.Empty,
                    out ParameterModifier missing) &&
                missing == null;
            Debug.Assert(missingPassed, "未登録補正の検索", this);
            Check(missingPassed, "未登録補正の検索");

            bool removePassed =
                parameter.TryRemoveModifier(modifier.Id) &&
                parameter.ModifierCount == 0 &&
                parameter.Value == 4f;
            Debug.Assert(removePassed, "補正の解除", this);
            Check(removePassed, "補正の解除");

            bool missingRemovePassed =
                !parameter.TryRemoveModifier(modifier.Id);
            Debug.Assert(
                missingRemovePassed,
                "未登録補正の解除",
                this);
            Check(missingRemovePassed, "未登録補正の解除");
        }

        /// <summary>
        /// 補正元による一括解除を検証する。
        /// </summary>
        private void TestSourceRemoval()
        {
            var parameter = CreateParameter();

            // 独立した補正元を生成する。
            object sourceA = new object();
            object sourceB = new object();

            parameter.TryAddModifier(
                ParameterModifier.CreateAdditive(1f, sourceA));

            parameter.TryAddModifier(
                ParameterModifier.CreateMultiplicative(
                    1.5f,
                    sourceA));

            parameter.TryAddModifier(
                ParameterModifier.CreateAdditive(1f, sourceB));

            bool countPassed = parameter.ModifierCount == 3;
            Debug.Assert(countPassed, "複数補正元の登録", this);
            Check(countPassed, "複数補正元の登録");

            bool removePassed =
                parameter.RemoveModifiersBySource(sourceA) == 2;
            Debug.Assert(removePassed, "同一補正元の一括解除", this);
            Check(removePassed, "同一補正元の一括解除");

            bool remainingPassed =
                parameter.ModifierCount == 1 &&
                parameter.Modifiers[0].IsFromSource(sourceB) &&
                parameter.Value == 5f;
            Debug.Assert(remainingPassed, "他の補正元の維持", this);
            Check(remainingPassed, "他の補正元の維持");

            bool missingPassed =
                parameter.RemoveModifiersBySource(sourceA) == 0;
            Debug.Assert(missingPassed, "未登録補正元の解除", this);
            Check(missingPassed, "未登録補正元の解除");

            bool nullPassed =
                parameter.RemoveModifiersBySource(null) == 0;
            Debug.Assert(nullPassed, "null補正元の解除", this);
            Check(nullPassed, "null補正元の解除");
        }

        /// <summary>
        /// 基本値と補正情報のリセットを検証する。
        /// </summary>
        private void TestReset()
        {
            var parameter =
                new RuntimeParameter<string>(
                    CreateDefinition(),
                    3f);

            parameter.SetBaseValue(5f);

            parameter.TryAddModifier(
                ParameterModifier.CreateAdditive(2f));

            bool baseResetPassed =
                parameter.ResetBaseValue() &&
                parameter.BaseValue == 3f &&
                parameter.Value == 5f;
            Debug.Assert(baseResetPassed, "基本値のみのリセット", this);
            Check(baseResetPassed, "基本値のみのリセット");

            bool keepPassed = parameter.ModifierCount == 1;
            Debug.Assert(keepPassed, "リセット時の補正維持", this);
            Check(keepPassed, "リセット時の補正維持");

            bool clearPassed =
                parameter.ClearModifiers() == 1 &&
                parameter.Value == 3f &&
                !parameter.HasModifiers;
            Debug.Assert(clearPassed, "全補正の解除", this);
            Check(clearPassed, "全補正の解除");

            bool emptyPassed = parameter.ClearModifiers() == 0;
            Debug.Assert(emptyPassed, "空の補正一覧の解除", this);
            Check(emptyPassed, "空の補正一覧の解除");

            parameter.SetBaseValue(8f);

            parameter.TryAddModifier(
                ParameterModifier.CreateMultiplicative(0.5f));

            parameter.Reset();

            bool resetPassed =
                parameter.BaseValue == 3f &&
                parameter.Value == 3f &&
                parameter.ModifierCount == 0;
            Debug.Assert(resetPassed, "完全リセット", this);
            Check(resetPassed, "完全リセット");
        }

        /// <summary>
        /// 最終値の変更通知と再入対策を検証する。
        /// </summary>
        private void TestEvents()
        {
            var parameter = CreateParameter();

            // イベントの発生件数。
            int eventCount = 0;

            // 最後に通知された変更前の値。
            float previousValue = 0f;

            // 最後に通知された変更後の値。
            float newValue = 0f;

            // 通知時点で状態が更新されているかどうか。
            bool stateUpdated = false;

            Action<float, float> handler = (previous, current) =>
            {
                eventCount++;
                previousValue = previous;
                newValue = current;

                stateUpdated = parameter.Value == current;
            };

            parameter.ValueChanged += handler;

            try
            {
                parameter.SetBaseValue(5f);

                bool countPassed = eventCount == 1;
                Debug.Assert(countPassed, "変更イベントの発生", this);
                Check(countPassed, "変更イベントの発生");

                bool argumentsPassed =
                    previousValue == 4f &&
                    newValue == 5f;
                Debug.Assert(argumentsPassed, "イベント引数", this);
                Check(argumentsPassed, "イベント引数");

                Debug.Assert(stateUpdated, "通知前の状態更新", this);
                Check(stateUpdated, "通知前の状態更新");

                parameter.SetBaseValue(5f);

                parameter.TryAddModifier(
                    ParameterModifier.CreateAdditive(0f));

                bool unchangedPassed = eventCount == 1;
                Debug.Assert(unchangedPassed, "値不変時の通知省略", this);
                Check(unchangedPassed, "値不変時の通知省略");

                object source = new object();

                parameter.TryAddModifier(
                    ParameterModifier.CreateAdditive(1f, source));

                parameter.TryAddModifier(
                    ParameterModifier.CreateAdditive(1f, source));

                int beforeRemoval = eventCount;

                parameter.RemoveModifiersBySource(source);

                bool batchPassed =
                    eventCount == beforeRemoval + 1;
                Debug.Assert(batchPassed, "一括解除時の単一通知", this);
                Check(batchPassed, "一括解除時の単一通知");

                // 通知中の再変更が拒否されることを確認する。
                bool reentryRejected = false;

                Action<float, float> reentryHandler =
                    (previous, current) =>
                    {
                        reentryRejected =
                            Throws<InvalidOperationException>(() =>
                            {
                                parameter.SetBaseValue(1f);
                            });
                    };

                parameter.ValueChanged += reentryHandler;

                try
                {
                    parameter.SetBaseValue(6f);
                }
                finally
                {
                    parameter.ValueChanged -= reentryHandler;
                }

                bool reentryPassed =
                    reentryRejected &&
                    parameter.Value == 6f;
                Debug.Assert(reentryPassed, "イベントの再入防止", this);
                Check(reentryPassed, "イベントの再入防止");
            }
            finally
            {
                parameter.ValueChanged -= handler;
            }

            int beforeUnsubscribe = eventCount;

            parameter.SetBaseValue(7f);

            bool unsubscribePassed =
                eventCount == beforeUnsubscribe;
            Debug.Assert(unsubscribePassed, "イベントの購読解除", this);
            Check(unsubscribePassed, "イベントの購読解除");
        }

        /// <summary>
        /// 同一の定義から生成した個体の独立性を検証する。
        /// </summary>
        private void TestIndependence()
        {
            var definition = CreateDefinition();

            var first =
                new RuntimeParameter<string>(definition);

            var second =
                new RuntimeParameter<string>(definition);

            first.SetBaseValue(6f);

            bool basePassed =
                first.BaseValue == 6f &&
                second.BaseValue == 4f;
            Debug.Assert(basePassed, "個体別の基本値管理", this);
            Check(basePassed, "個体別の基本値管理");

            first.TryAddModifier(
                ParameterModifier.CreateAdditive(2f));

            bool modifierPassed =
                first.Value == 8f &&
                second.Value == 4f &&
                second.ModifierCount == 0;
            Debug.Assert(modifierPassed, "個体別の補正管理", this);
            Check(modifierPassed, "個体別の補正管理");

            bool normalizedPassed =
                Mathf.Approximately(
                    first.NormalizedValue,
                    0.8f) &&
                Mathf.Approximately(
                    second.NormalizedValue,
                    0.4f);
            Debug.Assert(normalizedPassed, "個体別の正規化値", this);
            Check(normalizedPassed, "個体別の正規化値");
        }

        /// <summary>
        /// 不正な引数が拒否されることを検証する。
        /// </summary>
        private void TestInvalidInput()
        {
            bool nullDefinitionPassed =
                Throws<ArgumentNullException>(() =>
                {
                    new RuntimeParameter<string>(null);
                });
            Debug.Assert(
                nullDefinitionPassed,
                "null定義の拒否",
                this);
            Check(nullDefinitionPassed, "null定義の拒否");

            bool initialPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    new RuntimeParameter<string>(
                        CreateDefinition(),
                        20f);
                });
            Debug.Assert(initialPassed, "不正初期値の拒否", this);
            Check(initialPassed, "不正初期値の拒否");

            var parameter = CreateParameter();

            bool nanPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    parameter.SetBaseValue(float.NaN);
                });
            Debug.Assert(nanPassed, "NaN基本値の拒否", this);
            Check(nanPassed, "NaN基本値の拒否");

            bool infinityPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    parameter.AddBaseValue(float.PositiveInfinity);
                });
            Debug.Assert(infinityPassed, "無限大加算量の拒否", this);
            Check(infinityPassed, "無限大加算量の拒否");

            bool modifierPassed =
                Throws<ArgumentNullException>(() =>
                {
                    parameter.TryAddModifier(null);
                });
            Debug.Assert(modifierPassed, "null補正の拒否", this);
            Check(modifierPassed, "null補正の拒否");
        }

        /// <summary>
        /// 指定された処理が期待する例外を発生させるか検証する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">検証対象の処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();
            }
            catch (Exception exception)
            {
                // 期待する例外型との完全一致を確認する。
                if (exception.GetType() == typeof(TException))
                {
                    return true;
                }

                throw;
            }

            return false;
        }

        /// <summary>
        /// 個別のテスト結果を出力し、結果を集計する。
        /// </summary>
        /// <param name="passed">テストの成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
